'use strict';
const $=s=>document.querySelector(s);let enabled=false,mode='login',busy=false;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function message(text,error=false){$('#auth-message').className='alert '+(error?'error':'success');$('#auth-message').textContent=text;}
async function api(path,p){const res=await fetch('/api/auth/'+path,{method:p?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Top-Hills':'1'},body:p?JSON.stringify(p):undefined,signal:AbortSignal.timeout(20000)});const v=await res.json();if(!res.ok)throw Error(v.error||'Permintaan belum berhasil. Coba kembali.');return v;}
function render(){const labels={login:'Masuk',signup:'Daftar akun tim',confirm:'Konfirmasi email',recover:'Kirim kode pemulihan',reset:'Simpan kata sandi baru'},hasPassword=['login','signup','reset'].includes(mode);$('#auth-view').innerHTML=`${!enabled?'<div class="alert">Login email sedang menunggu koneksi Supabase dari Owner. Untuk sementara, masuk menggunakan ChatGPT.</div>':''}<div class="card"><div class="row" style="margin-bottom:24px"><button data-mode="login" class="${mode==='login'?'primary':''}">Masuk</button><button data-mode="signup" class="${mode==='signup'?'primary':''}">Daftar</button></div><form id="auth-form" class="grid"><fieldset class="full" ${enabled?'':'disabled'} style="border:0;margin:0;padding:0;display:grid;gap:18px">${mode==='signup'?'<label>Nama lengkap<input name="name" autocomplete="name" required minlength="2" maxlength="150"></label><label>Peran yang diajukan<select name="role"><option>Operator</option><option>Owner</option></select></label>':''}<label>Email<input type="email" name="email" required autocomplete="username" maxlength="254"></label>${['confirm','reset'].includes(mode)?'<label>Kode dari email<input name="code" autocomplete="one-time-code" inputmode="numeric" required maxlength="20"></label>':''}${hasPassword?`<label>${mode==='reset'?'Kata sandi baru':'Kata sandi'}<input id="password" name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" required minlength="${mode==='login'?1:12}" maxlength="128"></label><button id="show-password" type="button">Tampilkan kata sandi</button>`:''}${mode==='signup'?'<p class="muted">Minimal 12 karakter. Email harus dikonfirmasi. Peran yang diajukan tidak langsung aktif; Owner meninjau setiap akun.</p>':''}<button class="primary" type="submit">${labels[mode]}</button></fieldset></form><div class="row" style="margin-top:20px"><button data-mode="recover">Lupa kata sandi?</button><button data-mode="confirm">Punya kode konfirmasi</button><button data-mode="reset">Punya kode pemulihan</button></div></div><div class="card"><a id="chatgpt-signin" class="button" href="/signin-with-chatgpt?return_to=%2F" target="_top">Masuk dengan ChatGPT</a><p class="muted">Pilihan untuk akun tim yang sudah memakai ChatGPT.</p></div>`;$('#chatgpt-signin').onclick=async e=>{e.preventDefault();try{await api('logout',{});location.assign('/signin-with-chatgpt?return_to=%2F')}catch(err){message(err.message,true)}};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(busy)return;mode=b.dataset.mode;render()});$('#show-password')?.addEventListener('click',e=>{const input=$('#password');input.type=input.type==='password'?'text':'password';e.target.textContent=input.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi'});$('#auth-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const btn=e.submitter;btn.disabled=true;btn.textContent='Memproses…';try{const v=await api(mode,Object.fromEntries(new FormData(e.target)));if(v.redirect){location.assign(v.redirect);return;}message(v.message);e.target.reset();}catch(e){message(e.name==='TimeoutError'?'Koneksi lambat. Coba lagi; kata sandi tidak disimpan di perangkat.':e.message,true);}finally{busy=false;btn.disabled=false;btn.textContent=labels[mode]}};}
api('config').then(v=>{enabled=v.enabled;render()}).catch(e=>{render();message(e.message,true)});
